import openpyxl
import os

in_path = os.environ['IN_XLSX']
out_path = os.environ['OUT_XLSX']

wb = openpyxl.load_workbook(in_path)
ws = wb.active

# Read the pay out grid (P3:T6)
payout_grid = {}
for row in range(3, 7):
    for col in range(16, 21):  # P=16, Q=17, R=18, S=19, T=20
        val = ws.cell(row=row, column=col).value
        payout_grid[(row, col)] = val

# Determine variance row
def get_variance_row(variance):
    if variance < 0.03:
        return 3
    elif variance < 0.05:
        return 4
    elif variance < 0.07:
        return 5
    else:
        return 6

# Determine metric2 column
def get_metric2_col(metric2):
    if metric2 < -0.1:
        return 16  # P
    elif metric2 < 0:
        return 17  # Q
    elif metric2 < 0.1:
        return 18  # R
    elif metric2 < 0.2:
        return 19  # S
    else:
        return 20  # T

# Write incentives to G2:G19
for row in range(2, 20):
    variance = ws.cell(row=row, column=5).value
    metric2 = ws.cell(row=row, column=6).value
    vrow = get_variance_row(variance)
    mcol = get_metric2_col(metric2)
    incentive = payout_grid[(vrow, mcol)]
    ws.cell(row=row, column=7).value = incentive

wb.save(out_path)
print("Done. Incentives written to G2:G19.")
